      --primary-strong: #1d4ed8;
      --focus: #0f62fe;
      --shadow: 0 20px 50px rgba(15, 23, 42, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      margin: 0;
      min-height: 100%;
    }

    body {
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 38%),
        var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    .page {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .card {
      width: min(100%, 520px);
      background: var(--surface);
      border: 1px solid rgba(215, 224, 234, 0.9);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(24px, 4vw, 36px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin: 0 0 12px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--primary-strong);
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.6rem, 3vw, 2.2rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lead {
      margin: 12px 0 28px;
      color: var(--muted);
      max-width: 40ch;
    }

    form {
      display: grid;
      gap: 24px;
    }

    .form-field {
      display: grid;
      gap: 10px;
      padding: 18px;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface-2);
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 12px;
    }

    .checkbox-row input {
      margin-top: 2px;
      width: 1.1rem;
      height: 1.1rem;
      accent-color: var(--primary);
      flex: 0 0 auto;
    }

    .checkbox-row label {
      font-weight: 600;
      color: var(--text);
      cursor: pointer;
    }

    .required-mark {
      margin-left: 0.2rem;
      color: var(--primary-strong);
    }

    .help-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .status {
      margin: 0;
      padding: 14px 16px;
      border-radius: 14px;
      background: rgba(37, 99, 235, 0.08);
      color: var(--primary-strong);
      font-weight: 600;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      min-height: 48px;
      font: inherit;
      font-weight: 700;
      color: white;
      background: linear-gradient(135deg, var(--primary), var(--primary-strong));
      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.03);
    }

    button:focus-visible,
    input:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 420px) {
      .page {
        padding: 16px;
      }

      .card {
        padding: 20px;
      }

      .actions {
        justify-content: flex-start;
      }

      button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field {
        border: 1px solid CanvasText;
      }

      button {
        forced-color-adjust: auto;
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const CheckboxField = () => `
      <div class="form-field">
        <div class="checkbox-row">
          <input
            id="agree-terms"
            name="agreeTerms"
            type="checkbox"
            required
            aria-describedby="agree-terms-help"
          />
          <label for="agree-terms">
            I agree to the Terms of Use<span class="required-mark" aria-hidden="true">*</span>
          </label>
        </div>
        <p id="agree-terms-help" class="help-text">Required to proceed.</p>
      </div>
    `;

    const Form = () => `
      <form id="consent-form">
        ${CheckboxField()}
        <p id="form-status" class="status" aria-live="polite" hidden></p>
        <div class="actions">
          <button type="submit">Continue</button>
        </div>
      </form>
    `;

    const App = () => `
      <main class="page">
        <section class="card" aria-labelledby="page-title">
          <p class="eyebrow">Product access</p>
          <h1 id="page-title">Agree to the terms to continue</h1>
          <p class="lead">A quick consent step before you move forward.</p>
          ${Form()}
        </section>
      </main>
    `;

    document.getElementById("app").innerHTML = App();

    const form = document.getElementById("consent-form");
    const status = document.getElementById("form-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      status.hidden = false;
      status.textContent = "Consent recorded. You can continue.";
    });
  </script>
</body>
</html>
