import fs from 'fs';
import { JSDOM } from 'jsdom';
import axe from 'axe-core';

const html = fs.readFileSync('/workspace/sandbox/skills/building-accessible-ui/single-checkbox--framework-react--style-modern/gpt-5.4-mini__s2/index.html', 'utf8');
const dom = new JSDOM(html, { runScripts: 'dangerously', resources: 'usable' });
const { document, Node } = dom.window;
dom.window.eval(axe.source);

const checkbox = document.querySelector('#agree-terms');
const label = document.querySelector('label[for="agree-terms"]');
const formField = document.querySelector('.form-field');
const help = document.querySelector('#agree-terms-help');
const submit = document.querySelector('button[type="submit"]');

const assertions = [
  [!!checkbox, 'checkbox exists'],
  [checkbox?.required === true, 'checkbox is required'],
  [label?.textContent.includes('I agree to the Terms of Use'), 'label text is present'],
  [!!formField, 'checkbox is wrapped in .form-field'],
  [help?.id === 'agree-terms-help', 'helper text exists'],
  [checkbox?.getAttribute('aria-describedby') === 'agree-terms-help', 'helper text is associated'],
  [!!submit, 'submit button exists'],
];

const failed = assertions.filter(([ok]) => !ok).map(([, msg]) => msg);
const results = await dom.window.axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa'] } });
const violations = results.violations.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) }));

console.log(JSON.stringify({ failed, violations }, null, 2));
if (failed.length || violations.length) process.exit(1);
